    file: '<template>\n  <!-- \n    Gradient background CTA with stats\n    Features: Full-width gradient, statistics badges, animated blobs\n  -->\n  <div\n    class="from-primary/10 via-background to-primary/5 relative overflow-hidden bg-linear-to-br py-20"\n  >\n    <!-- Animated background blobs -->\n    <div class="absolute inset-0 overflow-hidden">\n      <Motion\n        :variants="{\n          initial: { scale: 0.8, opacity: 0.3 },\n          animate: {\n            scale: [0.8, 1, 0.8],\n            opacity: [0.3, 0.5, 0.3],\n            transition: {\n              duration: 8,\n              repeat: Infinity,\n              ease: \'easeInOut\',\n            },\n          },\n        }"\n        initial="initial"\n        animate="animate"\n        class="bg-primary/20 absolute -top-20 -right-20 h-96 w-96 rounded-full blur-3xl"\n      />\n      <Motion\n        :variants="{\n          initial: { scale: 0.8, opacity: 0.3 },\n          animate: {\n            scale: [0.8, 1.2, 0.8],\n            opacity: [0.3, 0.4, 0.3],\n            transition: {\n              duration: 10,\n              repeat: Infinity,\n              ease: \'easeInOut\',\n              delay: 2,\n            },\n          },\n        }"\n        initial="initial"\n        animate="animate"\n        class="bg-primary/15 absolute -bottom-32 -left-32 h-96 w-96 rounded-full blur-3xl"\n      />\n    </div>\n\n    <Motion\n      initial="initial"\n      while-in-view="animate"\n      :in-view-options="{ once: true }"\n      as-child\n      :variants="{\n        initial: { opacity: 0 },\n        animate: {\n          opacity: 1,\n          transition: {\n            when: \'beforeChildren\',\n            delayChildren: stagger(0.1),\n          },\n        },\n      }"\n    >\n      <UiContainer class="relative z-10 text-center">\n        <Motion\n          as="h2"\n          :variants="childVariant"\n          class="mb-4 text-4xl font-bold lg:mb-6 lg:text-5xl"\n        >\n          Ready to transform your business?\n        </Motion>\n        <Motion\n          as="p"\n          :variants="childVariant"\n          class="text-muted-foreground mx-auto mb-10 max-w-[700px] text-lg lg:text-xl"\n        >\n          Join thousands of companies already using {{ COMPANY_NAME }} to accelerate growth.\n        </Motion>\n\n        <Motion\n          :variants="childVariant"\n          class="mb-12 flex flex-wrap items-center justify-center gap-8"\n        >\n          <div v-for="stat in stats" :key="stat.label" class="text-center">\n            <div class="text-primary text-3xl font-bold lg:text-4xl">{{ stat.value }}</div>\n            <div class="text-muted-foreground mt-1 text-sm">{{ stat.label }}</div>\n          </div>\n        </Motion>\n\n        <Motion :variants="childVariant" class="flex flex-col justify-center gap-3 md:flex-row">\n          <UiButton size="lg" class="w-full md:w-auto">\n            Start free trial\n            <Icon name="lucide:arrow-right" class="ml-2 h-4 w-4" />\n          </UiButton>\n          <UiButton size="lg" variant="outline" class="w-full md:w-auto"> Schedule demo </UiButton>\n        </Motion>\n      </UiContainer>\n    </Motion>\n  </div>\n</template>\n\n<script lang="ts" setup>\n  import { stagger } from "motion-v";\n  import type { MotionProps } from "motion-v";\n\n  const childVariant: MotionProps["variants"] = {\n    initial: { opacity: 0, y: 20 },\n    animate: {\n      opacity: 1,\n      y: 0,\n      transition: {\n        type: "spring",\n        stiffness: 200,\n        damping: 20,\n      },\n    },\n  };\n\n  const stats = [\n    { value: "50K+", label: "Active users" },\n    { value: "99.9%", label: "Uptime" },\n    { value: "4.9/5", label: "User rating" },\n    { value: "24/7", label: "Support" },\n  ];\n</script>\n',
