    name: "Newsletter 4",
    fileName: "BlockNewsletter4.vue",
    file: '<template>\n  <Motion\n    initial="initial"\n    while-in-view="animate"\n    :in-view-options="{ once: true }"\n    as-child\n    :variants="containerVariant"\n  >\n    <UiContainer class="py-16 lg:py-24">\n      <UiCard class="overflow-hidden py-0">\n        <div class="grid gap-8 lg:grid-cols-2">\n          <Motion as-child :variants="contentVariant">\n            <div class="flex flex-col justify-center p-8 lg:p-12">\n              <h2 class="mb-4 text-3xl font-bold tracking-tight lg:text-4xl">\n                Join 10,000+ Subscribers\n              </h2>\n              <p class="text-muted-foreground mb-6 text-lg">\n                Get weekly insights, tips, and exclusive content delivered to your inbox. No spam,\n                ever.\n              </p>\n              <form class="flex flex-col gap-3 sm:flex-row">\n                <UiVeeInput\n                  class="flex-1"\n                  type="email"\n                  required\n                  placeholder="Your email address"\n                  aria-label="Your email address"\n                />\n                <UiButton type="submit" class="whitespace-nowrap">Get Started</UiButton>\n              </form>\n              <div class="text-muted-foreground mt-6 flex items-center gap-6 text-sm">\n                <div class="flex items-center gap-2">\n                  <Icon name="lucide:check-circle" class="text-primary size-5" />\n                  <span>Free forever</span>\n                </div>\n                <div class="flex items-center gap-2">\n                  <Icon name="lucide:shield-check" class="text-primary size-5" />\n                  <span>Secure</span>\n                </div>\n              </div>\n            </div>\n          </Motion>\n          <Motion as-child :variants="imageVariant">\n            <div class="from-primary/20 to-primary/5 relative h-64 bg-linear-to-br lg:h-auto">\n              <div class="absolute inset-0 flex items-center justify-center p-8">\n                <div class="grid grid-cols-2 gap-4">\n                  <div v-for="i in 4" :key="i" class="bg-card h-24 w-24 rounded-lg shadow-lg"></div>\n                </div>\n              </div>\n            </div>\n          </Motion>\n        </div>\n      </UiCard>\n    </UiContainer>\n  </Motion>\n</template>\n\n<script lang="ts" setup>\n  import { stagger } from "motion-v";\n  import type { MotionProps } from "motion-v";\n\n  const containerVariant: MotionProps["variants"] = {\n    initial: { opacity: 0 },\n    animate: {\n      opacity: 1,\n      transition: {\n        when: "beforeChildren",\n        delayChildren: stagger(0.15),\n      },\n    },\n  };\n\n  const contentVariant: MotionProps["variants"] = {\n    initial: { opacity: 0, x: -50 },\n    animate: {\n      opacity: 1,\n      x: 0,\n      transition: {\n        type: "spring",\n        stiffness: 200,\n        damping: 20,\n      },\n    },\n  };\n\n  const imageVariant: MotionProps["variants"] = {\n    initial: { opacity: 0, x: 50 },\n    animate: {\n      opacity: 1,\n      x: 0,\n      transition: {\n        type: "spring",\n        stiffness: 200,\n        damping: 20,\n        delay: 0.2,\n      },\n    },\n  };\n</script>\n',
