    file: '<template>\n  <UiSidebarProvider>\n    <!-- App Sidebar -->\n    <UiSidebar>\n      <UiSidebarHeader>\n        <!-- Version switcher -->\n        <UiSidebarMenu>\n          <UiSidebarMenuItem>\n            <UiDropdownMenu>\n              <UiDropdownMenuTrigger as-child>\n                <UiSidebarMenuButton\n                  size="lg"\n                  class="data-[state=open]:bg-sidebar-accent data-[state=open]:text-sidebar-accent-foreground"\n                >\n                  <div\n                    class="bg-sidebar-primary text-sidebar-primary-foreground flex aspect-square size-8 items-center justify-center rounded-lg"\n                  >\n                    <Icon name="lucide:gallery-vertical-end" class="size-4" />\n                  </div>\n                  <div class="flex flex-col gap-0.5 leading-none">\n                    <span class="font-semibold">Documentation</span>\n                    <span class="">v{{ selectedVersion }}</span>\n                  </div>\n                  <Icon name="lucide:chevrons-up-down" class="ml-auto" />\n                </UiSidebarMenuButton>\n              </UiDropdownMenuTrigger>\n              <UiDropdownMenuContent class="w-(--reka-dropdown-menu-trigger-width)" align="start">\n                <UiDropdownMenuItem\n                  v-for="version in data.versions"\n                  :key="version"\n                  class="cursor-pointer"\n                  @select="selectedVersion = version"\n                >\n                  v{{ version }}\n                  <Icon v-if="version === selectedVersion" name="lucide:check" class="ml-auto" />\n                </UiDropdownMenuItem>\n              </UiDropdownMenuContent>\n            </UiDropdownMenu>\n          </UiSidebarMenuItem>\n        </UiSidebarMenu>\n        <!-- Search form -->\n        <form>\n          <UiSidebarGroup class="py-0">\n            <UiSidebarGroupContent class="relative">\n              <UiLabel for="search" class="sr-only"> Search </UiLabel>\n              <UiSidebarInput id="search" placeholder="Search the docs..." class="pl-8" />\n              <Icon\n                name="lucide:search"\n                class="pointer-events-none absolute top-1/2 left-2 size-4 -translate-y-1/2 opacity-50 select-none"\n              />\n            </UiSidebarGroupContent>\n          </UiSidebarGroup>\n        </form>\n      </UiSidebarHeader>\n      <UiSidebarContent>\n        <!-- We create a SidebarGroup for each parent. -->\n        <template v-for="item in data.navMain" :key="item.title">\n          <UiSidebarGroup>\n            <UiSidebarGroupLabel :label="item.title" />\n            <UiSidebarGroupContent>\n              <UiSidebarMenu>\n                <template v-for="child in item.items" :key="`child-${child.title}`">\n                  <UiSidebarMenuItem>\n                    <UiSidebarMenuButton as-child :is-active="child.isActive">\n                      <NuxtLink :href="child.url">{{ child.title }}</NuxtLink>\n                    </UiSidebarMenuButton>\n                  </UiSidebarMenuItem>\n                </template>\n              </UiSidebarMenu>\n            </UiSidebarGroupContent>\n          </UiSidebarGroup>\n        </template>\n      </UiSidebarContent>\n      <UiSidebarRail />\n    </UiSidebar>\n    <!-- Sidebar main content -->\n    <UiSidebarInset>\n      <!-- Navbar -->\n      <UiNavbar sticky class="flex h-16 shrink-0 items-center gap-2 border-b px-4">\n        <UiSidebarTrigger class="-ml-1" />\n        <UiDivider orientation="vertical" class="mr-2 h-4 w-px" />\n        <UiBreadcrumbs :items="breadcrumbItems" />\n      </UiNavbar>\n      <div class="flex flex-1 flex-col gap-4 p-4">\n        <div class="grid auto-rows-min gap-4 md:grid-cols-3">\n          <UiPlaceholder v-for="n in 3" :key="n" class="aspect-video rounded-lg" />\n        </div>\n        <UiPlaceholder class="min-h-dvh flex-1 rounded-lg md:min-h-min" />\n      </div>\n    </UiSidebarInset>\n  </UiSidebarProvider>\n</template>\n\n<script lang="ts" setup>\n  // Breadcrumb items\n  const breadcrumbItems = [\n    { label: "Building Your Application", link: "#" },\n    { label: "Data Fetching", link: "#" },\n  ];\n  // This is sample data.\n  const data = {\n    versions: ["1.0.1", "1.1.0-alpha", "2.0.0-beta1"],\n    navMain: [\n      {\n        title: "Getting Started",\n        url: "#",\n        items: [\n          {\n            title: "Installation",\n            url: "#",\n          },\n          {\n            title: "Project Structure",\n            url: "#",\n          },\n        ],\n      },\n      {\n        title: "Building Your Application",\n        url: "#",\n        items: [\n          {\n            title: "Routing",\n            url: "#",\n          },\n          {\n            title: "Data Fetching",\n            url: "#",\n            isActive: true,\n          },\n          {\n            title: "Rendering",\n            url: "#",\n          },\n          {\n            title: "Caching",\n            url: "#",\n          },\n          {\n            title: "Styling",\n            url: "#",\n          },\n          {\n            title: "Optimizing",\n            url: "#",\n          },\n          {\n            title: "Configuring",\n            url: "#",\n          },\n          {\n            title: "Testing",\n            url: "#",\n          },\n          {\n            title: "Authentication",\n            url: "#",\n          },\n          {\n            title: "Deploying",\n            url: "#",\n          },\n          {\n            title: "Upgrading",\n            url: "#",\n          },\n          {\n            title: "Examples",\n            url: "#",\n          },\n        ],\n      },\n      {\n        title: "API Reference",\n        url: "#",\n        items: [\n          {\n            title: "Components",\n            url: "#",\n          },\n          {\n            title: "File Conventions",\n            url: "#",\n          },\n          {\n            title: "Functions",\n            url: "#",\n          },\n          {\n            title: "next.config.js Options",\n            url: "#",\n          },\n          {\n            title: "CLI",\n            url: "#",\n          },\n          {\n            title: "Edge Runtime",\n            url: "#",\n          },\n        ],\n      },\n      {\n        title: "Architecture",\n        url: "#",\n        items: [\n          {\n            title: "Accessibility",\n            url: "#",\n          },\n          {\n            title: "Fast Refresh",\n            url: "#",\n          },\n          {\n            title: "Next.js Compiler",\n            url: "#",\n          },\n          {\n            title: "Supported Browsers",\n            url: "#",\n          },\n          {\n            title: "Turbopack",\n            url: "#",\n          },\n        ],\n      },\n    ],\n  };\n  const selectedVersion = ref(data.versions[0]);\n  useSeoMeta({ title: "Sidebar 01" });\n</script>\n',
