    file: '<template>\n  <UiSidebarProvider>\n    <UiSidebar>\n      <UiSidebarContent>\n        <UiSidebarGroup>\n          <UiSidebarGroupLabel label="Projects" />\n          <UiSidebarGroupAction title="Add Project">\n            <Icon name="lucide:plus" /> <span class="sr-only">Add Project</span>\n          </UiSidebarGroupAction>\n          <UiSidebarGroupContent>\n            <UiSidebarMenu>\n              <UiSidebarMenuItem v-for="item in items" :key="item.title">\n                <UiSidebarMenuButton as-child>\n                  <a :href="item.url">\n                    <Icon :name="item.icon" />\n                    <span>{{ item.title }}</span>\n                  </a>\n                </UiSidebarMenuButton>\n              </UiSidebarMenuItem>\n            </UiSidebarMenu>\n          </UiSidebarGroupContent>\n        </UiSidebarGroup>\n      </UiSidebarContent>\n    </UiSidebar>\n    <UiSidebarInset>\n      <UiNavbar sticky>\n        <UiContainer class="flex h-12 items-center">\n          <UiSidebarTrigger />\n        </UiContainer>\n      </UiNavbar>\n    </UiSidebarInset>\n  </UiSidebarProvider>\n</template>\n\n<script lang="ts" setup>\n  // Menu items.\n  const items = [\n    { title: "Home", url: "#", icon: "lucide:home" },\n    { title: "Inbox", url: "#", icon: "lucide:inbox" },\n    { title: "Calendar", url: "#", icon: "lucide:calendar" },\n    { title: "Search", url: "#", icon: "lucide:search" },\n    { title: "Settings", url: "#", icon: "lucide:settings" },\n  ];\n</script>\n',
