    file: '<template>\n  <Motion\n    initial="initial"\n    while-in-view="animate"\n    :in-view-options="{ once: true }"\n    as-child\n    :variants="parentVariant"\n  >\n    <UiContainer class="py-16 lg:py-24">\n      <Motion as-child :variants="childVariant">\n        <div class="mb-12">\n          <p class="text-primary mb-3 text-center font-semibold">The Team</p>\n          <h2 class="mb-4 text-center text-4xl font-bold lg:text-5xl">\n            Meet the people making it happen\n          </h2>\n        </div>\n      </Motion>\n\n      <div class="space-y-16">\n        <Motion\n          v-for="department in departments"\n          :key="department.name"\n          as-child\n          :variants="sectionVariant"\n        >\n          <div>\n            <h3 class="mb-6 text-2xl font-bold">{{ department.name }}</h3>\n            <div class="grid gap-6 sm:grid-cols-2 lg:grid-cols-4">\n              <div\n                v-for="member in department.members"\n                :key="member.name"\n                class="group flex flex-col items-center text-center"\n              >\n                <div class="relative mb-4">\n                  <UiAvatar\n                    class="ring-ring/20 group-hover:ring-primary/50 h-32 w-32 ring-2 transition-all group-hover:ring-4"\n                    :src="member.avatar"\n                  />\n                  <div\n                    class="bg-primary text-primary-foreground absolute -right-2 -bottom-2 rounded-full px-3 py-1 text-xs font-semibold"\n                  >\n                    {{ member.badge }}\n                  </div>\n                </div>\n                <p class="mb-1 font-semibold">{{ member.name }}</p>\n                <p class="text-primary mb-2 text-sm">{{ member.role }}</p>\n                <p class="text-muted-foreground text-xs">{{ member.location }}</p>\n              </div>\n            </div>\n          </div>\n        </Motion>\n      </div>\n    </UiContainer>\n  </Motion>\n</template>\n\n<script lang="ts" setup>\n  import { stagger } from "motion-v";\n  import type { MotionProps } from "motion-v";\n\n  const departments = [\n    {\n      name: "Leadership",\n      members: [\n        {\n          name: "Sarah Johnson",\n          role: "CEO",\n          location: "San Francisco, US",\n          badge: "Founder",\n          avatar: "https://i.pravatar.cc/150?img=1",\n        },\n        {\n          name: "Michael Chen",\n          role: "CTO",\n          location: "Singapore, SG",\n          badge: "Founder",\n          avatar: "https://i.pravatar.cc/150?img=2",\n        },\n        {\n          name: "Emily Davis",\n          role: "COO",\n          location: "London, UK",\n          badge: "New",\n          avatar: "https://i.pravatar.cc/150?img=3",\n        },\n        {\n          name: "David Kim",\n          role: "CFO",\n          location: "Seoul, KR",\n          badge: "New",\n          avatar: "https://i.pravatar.cc/150?img=4",\n        },\n      ],\n    },\n    {\n      name: "Engineering",\n      members: [\n        {\n          name: "Alex Martinez",\n          role: "Lead Engineer",\n          location: "Barcelona, ES",\n          badge: "Team Lead",\n          avatar: "https://i.pravatar.cc/150?img=5",\n        },\n        {\n          name: "Lisa Wang",\n          role: "Senior Developer",\n          location: "Toronto, CA",\n          badge: "Core",\n          avatar: "https://i.pravatar.cc/150?img=6",\n        },\n        {\n          name: "James Brown",\n          role: "DevOps Engineer",\n          location: "Berlin, DE",\n          badge: "Core",\n          avatar: "https://i.pravatar.cc/150?img=7",\n        },\n        {\n          name: "Maria Garcia",\n          role: "QA Engineer",\n          location: "Mexico City, MX",\n          badge: "New",\n          avatar: "https://i.pravatar.cc/150?img=8",\n        },\n      ],\n    },\n  ];\n\n  const parentVariant: MotionProps["variants"] = {\n    initial: { opacity: 0 },\n    animate: {\n      opacity: 1,\n      transition: {\n        when: "beforeChildren",\n        delayChildren: stagger(0.15),\n      },\n    },\n  };\n\n  const childVariant: MotionProps["variants"] = {\n    initial: { opacity: 0, y: 20 },\n    animate: {\n      opacity: 1,\n      y: 0,\n      transition: {\n        type: "spring",\n        stiffness: 200,\n        damping: 20,\n      },\n    },\n  };\n\n  const sectionVariant: MotionProps["variants"] = {\n    initial: { opacity: 0, y: 30 },\n    animate: {\n      opacity: 1,\n      y: 0,\n      transition: {\n        type: "spring",\n        stiffness: 200,\n        damping: 20,\n      },\n    },\n  };\n</script>\n',
